//! License-clean synthetic test chart.
//!
//! **Provenance (AGENTS.md §2.5, COLOR_PIPELINE §9):** every value in this
//! chart is generated by this file — mathematical ramps, saturated primaries,
//! and round-number sRGB triples authored for MELOGRAPHY. No third-party
//! measured data (e.g. X-Rite ColorChecker values) is used anywhere.
//! Recorded in `tests/assets/provenance.json`.
//!
//! Layout (768×512, sRGB code-value convention [0,1]):
//! * 32×32-cell grid (24×16 cells);
//! * rows 0–1: 21-step neutral ramp `i/20` at grid positions (1+i) of the
//!   combined sequence;
//! * row 2: saturated primaries/secondaries/white/black;
//! * row 3: seven skin-tone-inspired round sRGB triples (authored);
//! * row 4: six near-black steps `k·4/255`;
//! * bottom 64-px strip: smooth dark gradient 0 → 16/255 (banding test
//!   region for the dither gate);
//! * everything else: mid-gray 0.46.

use melography_core::{Channels, ImageF32};

/// Geometry constants of the chart (stable — golden tests depend on them).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ChartLayout {
    pub width: u32,
    pub height: u32,
    pub cell: u32,
    pub grid_cols: u32,
    pub grid_rows: u32,
    /// y coordinate where the dark gradient strip starts.
    pub strip_y: u32,
}

pub const CHART_LAYOUT: ChartLayout = ChartLayout {
    width: 768,
    height: 512,
    cell: 32,
    grid_cols: 24,
    grid_rows: 16,
    strip_y: 448,
};

/// Authored skin-tone-inspired patches (round sRGB code triples).
pub const SKINISH: [[f32; 3]; 7] = [
    [0.85, 0.62, 0.50],
    [0.78, 0.55, 0.42],
    [0.92, 0.72, 0.58],
    [0.65, 0.45, 0.35],
    [0.55, 0.48, 0.38],
    [0.40, 0.28, 0.22],
    [0.95, 0.82, 0.70],
];

/// Color of chart patch at grid cell `(gx, gy)`, or `None` for background.
#[must_use]
pub fn patch_color(gx: u32, gy: u32) -> Option<[f32; 3]> {
    use CHART_LAYOUT as L;
    if gx == 0 || gx >= L.grid_cols - 1 || gy >= L.grid_rows {
        return None;
    }
    match gy {
        0 | 1 => {
            // 21-step neutral ramp across two rows
            let idx = gy * (L.grid_cols - 2) + (gx - 1);
            if idx < 21 {
                let v = idx as f32 / 20.0;
                Some([v, v, v])
            } else {
                None
            }
        }
        2 => match gx {
            1 => Some([1.0, 0.0, 0.0]),
            2 => Some([0.0, 1.0, 0.0]),
            3 => Some([0.0, 0.0, 1.0]),
            4 => Some([0.0, 1.0, 1.0]),
            5 => Some([1.0, 0.0, 1.0]),
            6 => Some([1.0, 1.0, 0.0]),
            7 => Some([1.0, 1.0, 1.0]),
            _ => None,
        },
        3 => (1..=7).contains(&gx).then(|| SKINISH[(gx - 1) as usize]),
        4 => {
            if (1..=6).contains(&gx) {
                let v = (gx - 1) as f32 * 4.0 / 255.0;
                Some([v, v, v])
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Deterministic chart color at pixel `(x, y)`.
#[must_use]
pub fn chart_pixel(x: u32, y: u32) -> [f32; 3] {
    use CHART_LAYOUT as L;
    if y >= L.strip_y {
        // smooth dark gradient 0 → 16/255
        let v = x as f32 / (L.width - 1) as f32 * 16.0 / 255.0;
        return [v, v, v];
    }
    let gx = x / L.cell;
    let gy = y / L.cell;
    if let Some(c) = patch_color(gx, gy) {
        return c;
    }
    [0.46, 0.46, 0.46] // mid-gray background
}

/// Full synthetic chart as sRGB-encoded f32 (code-value convention).
#[must_use]
pub fn synthetic_chart() -> ImageF32 {
    use CHART_LAYOUT as L;
    let mut data = Vec::with_capacity((L.width as usize) * (L.height as usize) * 3);
    for y in 0..L.height {
        for x in 0..L.width {
            let [r, g, b] = chart_pixel(x, y);
            data.extend_from_slice(&[r, g, b]);
        }
    }
    ImageF32::from_interleaved(L.width, L.height, Channels::Rgb, data)
}

/// Chart rendered to 16-bit code values (for PNG roundtrip tests).
#[must_use]
pub fn synthetic_chart_u16() -> (u32, u32, Vec<u16>) {
    let chart = synthetic_chart();
    let px = chart
        .data()
        .iter()
        .map(|&c| (c.clamp(0.0, 1.0) * 65_535.0).round() as u16)
        .collect();
    (chart.width(), chart.height(), px)
}

/// 8-bit variant of [`synthetic_chart_u16`] (JPEG export path tests).
#[must_use]
pub fn synthetic_chart_u8() -> (u32, u32, Vec<u8>) {
    let (w, h, px16) = synthetic_chart_u16();
    let px8: Vec<u8> = px16.iter().map(|&v| (v >> 8) as u8).collect();
    (w, h, px8)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn chart_is_deterministic() {
        let a = synthetic_chart();
        let b = synthetic_chart();
        assert_eq!(a, b);
    }

    #[test]
    fn ramp_patch_values_are_exactly_i_over_20() {
        for i in 0..21u32 {
            let gx = i + 1;
            let gy = if gx < 23 { 0 } else { 1 };
            let c = patch_color(gx, gy).expect("ramp cell");
            let want = i as f32 / 20.0;
            assert_eq!(c, [want, want, want], "ramp {i}");
        }
    }

    #[test]
    fn dark_strip_reaches_16_255() {
        let last = chart_pixel(CHART_LAYOUT.width - 1, CHART_LAYOUT.height - 1);
        assert!((last[0] - 16.0 / 255.0).abs() < 1e-6);
        assert_eq!(chart_pixel(0, CHART_LAYOUT.strip_y)[0], 0.0);
    }

    #[test]
    fn background_is_midgray() {
        assert_eq!(chart_pixel(0, 200), [0.46, 0.46, 0.46]);
    }
}
